import{c as t,Q as a,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"Active Context Compression: Autonomous Memory Management in LLM Agents","description":"","frontmatter":{"url":"https://arxiv.org/abs/2601.07190","title":"Active Context Compression: Autonomous Memory Management in LLM Agents","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2601.0719,"authors":["Nikhil Verma"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2601.07190v1","pdf_path":"pdfs/2601.07190.pdf","published_date":"2026-01-12T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-01-12-active-context-compression-autonomous-memory-2601-07190.md","filePath":"research/papers/2026-01-12-active-context-compression-autonomous-memory-2601-07190.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-01-12-active-context-compression-autonomous-memory-2601-07190.md"};function s(i,e,c,l,u,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="active-context-compression-autonomous-memory-management-in-llm-agents" tabindex="-1">Active Context Compression: Autonomous Memory Management in LLM Agents <a class="header-anchor" href="#active-context-compression-autonomous-memory-management-in-llm-agents" aria-label="Permalink to &quot;Active Context Compression: Autonomous Memory Management in LLM Agents&quot;">​</a></h1><p><strong>Authors</strong>: Nikhil Verma <strong>Published</strong>: January 12, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2601.07190" target="_blank" rel="noreferrer">https://arxiv.org/abs/2601.07190</a> · <a href="https://arxiv.org/html/2601.07190v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2601.07190 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2601.07190" target="_blank" rel="noreferrer">research/papers/pdfs/2601.07190.pdf</a> (4 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Large Language Model (LLM) agents struggle with long-horizon software engineering tasks due to &#39;Context Bloat.&#39; As interaction history grows, computational costs explode, latency increases, and reasoning capabilities degrade due to distraction by irrelevant past errors. Existing solutions often rely on passive, external summarization mechanisms that the agent cannot control. This paper proposes Focus, an agent-centric architecture inspired by the biological exploration strategies of Physarum polycephalum (slime mold). The Focus Agent autonomously decides when to consolidate key learnings into a persistent &#39;Knowledge&#39; block and actively withdraws (prunes) the raw interaction history. Using an optimized scaffold matching industry best practices (persistent bash + string-replacement editor), we evaluated Focus on N=5 context-intensive instances from SWE-bench Lite using Claude Haiku 4.5. With aggressive prompting that encourages frequent compression, Focus achieves 22.7% token reduction (14.9M -&gt; 11.5M tokens) while maintaining identical accuracy (3/5 = 60% for both agents). Focus performed 6.0 autonomous compressions per task on average, with token savings up to 57% on individual instances. We demonstrate that capable models can autonomously self-regulate their context when given appropriate tools and prompting, opening pathways for cost-aware agentic systems without sacrificing task performance.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 Focus：agent-centric 架構，受黏菌（Physarum polycephalum）探索策略啟發。Agent 自主決定何時把關鍵學習整合進持久的 &#39;Knowledge&#39; block，並主動 prune（撤回）raw interaction history。</li><li>對比過往「被動、外部、agent 無法控制」的摘要機制，強調自主可控的 context 自我調節。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>於 SWE-bench Lite N=5 context-intensive 實例、用 Claude Haiku 4.5 評估：token 減少 22.7%（14.9M→11.5M），準確率不變（兩 agent 皆 3/5 = 60%）。</li><li>平均每任務 6.0 次自主壓縮，單一實例 token 節省最高 57%。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>文件自述 N=5（極小樣本，4 頁短文）；判斷弱點：統計效力弱、單一 backbone（Haiku 4.5）、aggressive prompting 下的壓縮品質未做退化分析。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>高度貼合本 workspace：以 Claude Haiku 4.5 + persistent bash + string-replacement editor 為 scaffold，幾乎是 <code>pilot</code>（tier=cost，原 <code>haiku-pilot</code>） + 本庫 Bash/Edit 工具鏈的鏡像。</li><li>「agent 自主決定何時 consolidate 並 prune raw history」對應 context-management 的主動 compact（30–35% 主動觸發）與 core.md RECORD checkpoint——把學習寫入 Knowledge block ≈ 更新 MEMORY/LESSONS。</li><li>⚠️ 落地門檻：N=5 樣本不足以背書；「aggressive 壓縮」與本庫「delta hint 防 context collapse」存在張力——自主 prune 須有 unverified_success 閘門防止刪掉 load-bearing 脈絡。</li></ul>',16)])])}const d=t(n,[["render",s]]);export{m as __pageData,d as default};
